    [19840]={name="Zandalar Haruspex's Bracers",sourceType="quest_reward",instructions="Reward from the quest “Paragons of Power: The Haruspex's Bracers”. In Zul'Gurub.",zone="Zul'Gurub",questName="Paragons of Power: The Haruspex's Bracers",lore="By communion with animals and givin' them up to the spirits when needed, they give us divine guidance. In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi."},
    [19857]={name="Cloak of Consumption",sourceType="boss_drop",instructions="Drops from Hakkar in Zul'Gurub.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
