    [21268]={name="Blessed Qiraji War Hammer",sourceType="quest_reward",instructions="Reward from the quest “Imperial Qiraji Regalia” — pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Regalia",lore="I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."},
