    [23031]={name="Band of the Inevitable",sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer in Naxxramas.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
    [23035]={name="Preceptor's Hat",sourceType="boss_drop",instructions="Drops from Heigan the Unclean in Naxxramas.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23036]={name="Necklace of Necropsy",sourceType="boss_drop",instructions="Drops from Heigan the Unclean in Naxxramas.",zone="Naxxramas",npc="Heigan the Unclean",lore="Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."},
    [23038]={name="Band of Unnatural Forces",sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
